'use strict';
const waveformCache=new Map();
function drawAudioWaveform(canvas,buffer,clip){const width=canvas.width,height=canvas.height,key=[clip.id,clip.offset,clip.duration,clip.rate||1,width].join(':'),saved=waveformCache.get(key);if(saved?.buffer===buffer){canvas.getContext('2d').putImageData(saved.pixels,0,0);return}const ctx=canvas.getContext('2d'),middle=height/2,rate=clip.rate||1;ctx.clearRect(0,0,width,height);ctx.fillStyle='#91d9d0';for(let x=0;x<width;x++){const first=Math.max(0,Math.floor((clip.offset+x/width*clip.duration*rate)*buffer.sampleRate)),last=Math.min(buffer.length,Math.ceil((clip.offset+(x+1)/width*clip.duration*rate)*buffer.sampleRate)),step=Math.max(1,Math.floor((last-first)/128));let peak=0;for(let ch=0;ch<buffer.numberOfChannels;ch++){const data=buffer.getChannelData(ch);for(let i=first;i<last;i+=step)peak=Math.max(peak,Math.abs(data[i]))}const bar=peak*(middle-1);if(bar>.05)ctx.fillRect(x,middle-bar,1,Math.max(1,bar*2))}ctx.strokeStyle='#91d9d044';ctx.beginPath();ctx.moveTo(0,middle+.5);ctx.lineTo(width,middle+.5);ctx.stroke();waveformCache.set(key,{buffer,pixels:ctx.getImageData(0,0,width,height)});while(waveformCache.size>48)waveformCache.delete(waveformCache.keys().next().value)}
const makeClipBeforeWaveforms=makeClip;makeClip=function(area,options){const el=makeClipBeforeWaveforms(area,options),clip=options.audioClip;if(!clip)return el;el.classList.add('has-audio-waveform');let canvas=el.querySelector('canvas.clip-wave');if(!options.buffer){const loading=document.createElement('span');loading.className='waveform-loading';loading.textContent='Loading waveform…';el.append(loading);return el}if(!canvas){canvas=document.createElement('canvas');canvas.className='clip-wave';el.prepend(canvas)}canvas.width=Math.min(8192,Math.max(2,Math.round((options.end-options.start)*timelineZoom)));canvas.height=28;canvas.setAttribute('aria-label','Waveform for '+clip.name);drawAudioWaveform(canvas,options.buffer,clip);return el};
const waveformStyle=document.createElement('style');waveformStyle.textContent='.timeline-clip.has-audio-waveform{height:43px;min-height:43px;background:#20423e;border-color:#5c9c94}.track-row:has(.has-audio-waveform){min-height:49px}.track-row:has(.has-audio-waveform) .track-lane{min-height:49px}.has-audio-waveform .clip-wave{position:absolute;left:0;bottom:0;top:auto;width:100%;height:28px;opacity:1;pointer-events:none}.has-audio-waveform .clip-name{position:relative;z-index:2;display:block;height:13px;font-size:10px;line-height:13px;text-shadow:0 1px 2px #000}.waveform-loading{position:absolute;left:7px;bottom:5px;font-size:9px;color:#bad5d0;pointer-events:none}';document.head.append(waveformStyle);renderTimeline();
